const MAX_PAGES = 0;
const baseUrl = "https://www.amazon.eg/s?i=electronics&rh=n%3A21832907031&fs=true";
const results = [];

for (let currentPage = 1; currentPage <= MAX_PAGES; currentPage++) {
    results.push({
        json: {
            page: currentPage,
            pageUrl: `${baseUrl}&page=${currentPage}`
        }
    });
}

return results;

// جلب HTML من العقدة الحالية
const htmlContent = $input.first().json.data || $input.first().json.body || "";

// التأكد مما إذا كانت الصفحة صفحة حماية (Bot Detection)
if (htmlContent.includes("validateCaptcha") || htmlContent.includes("robot check")) {
    throw new Error("تم حظر الطلب بواسطة Amazon Captcha! يرجى تغيير الـ User-Agent أو استخدام Proxy.");
}

// تقسيم الصفحة إلى أجزاء المنتجات
const blocks = htmlContent.split('data-component-type="s-search-result"').slice(1);
const results = [];

blocks.forEach(block => {
    // 1. استخراج عنوان المنتج
    const titleMatch = block.match(/<h2[^>]*>[\s\S]*?<span[^>]*>([\s\S]*?)<\/span>/i) ||
                       block.match(/class="a-text-normal"[^>]*>([\s\S]*?)<\/span>/i);

    let title = titleMatch ? titleMatch[1].replace(/<[^>]+>/g, '').trim() : null;
    if (title) {
        title = title.replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&#x27;/g, "'");
    }

    // 2. استخراج السعر بدقة عالية
    let price = null;

    // محاولة التقاط السعر المباشر من a-offscreen أو a-price-whole
    const priceOffscreen = block.match(/class="a-offscreen">([^<]+)<\/span>/i);
    const priceWhole = block.match(/class="a-price-whole">([^<]+)/i);
    const priceGeneral = block.match(/(?:EGP|جنيه|ج\.م)\s*([\d,٫\.]+)/i) || block.match(/([\d,٫\.]+)\s*(?:EGP|جنيه|ج\.م)/i);

    let rawPriceStr = "";
    if (priceOffscreen && priceOffscreen[1]) {
        rawPriceStr = priceOffscreen[1];
    } else if (priceWhole && priceWhole[1]) {
        rawPriceStr = priceWhole[1];
    } else if (priceGeneral && priceGeneral[1]) {
        rawPriceStr = priceGeneral[1];
    }

    if (rawPriceStr) {
        let cleanPriceStr = rawPriceStr
            .replace(/٫/g, '.')
            .replace(/,/g, '')
            .replace(/[^0-9.]/g, '');

        let parsedPrice = parseFloat(cleanPriceStr);
        if (!isNaN(parsedPrice) && parsedPrice > 0) {
            price = parsedPrice;
        }
    }

    // 3. استخراج التقييم
    let rating = null;
    const ratingMatch = block.match(/([0-9.]+)\s*(out of 5 stars|من 5 نجوم)/i) || 
                        block.match(/class="a-icon-alt">([^<]+)<\/span>/i);

    if (ratingMatch) {
        const numMatch = ratingMatch[0].match(/([0-9.]+)/);
        rating = numMatch ? parseFloat(numMatch[1]) : null;
    }

    // 4. استخراج حالة المخزون
    let stockStatus = "Available";
    const stockMatch = block.match(/Only\s*\d+\s*left in stock/i) || 
                       block.match(/متبقي\s*\d+\s*فقط/i);

    if (stockMatch) {
        stockStatus = stockMatch[0].trim();
    }

    // 5. استخراج رابط المنتج
    const urlMatch = block.match(/href="(\/dp\/[^"?\s]+|\/[^"?\s]+\/dp\/[^"?\s]+)"/i);
    let url = urlMatch ? `https://www.amazon.eg${urlMatch[1]}` : null;

    if (title) {
        results.push({
            json: {
                title: title,
                price_EGP: price,
                rating: rating,
                stock: stockStatus,
                url: url
            }
        });
    }
});

const titlesList = results.map((item, index) => `${index + 1}. ${item.json.title}`).join("\n");

return [{
    json: {
        all_titles: titlesList,
        raw_products: results
    }
}];

return $input.all().map(item => {
  const newItem = { ...item.json };

  delete newItem.title;

  return {
    json: newItem
  };
});

// 1. استخراج نص الذكاء الاصطناعي
const inputJson = $input.first().json;
let rawText = inputJson.text || inputJson.output || (inputJson.content?.parts?.[0]?.text) || "";

if (typeof rawText === 'object') {
    rawText = JSON.stringify(rawText);
}

// 2. تنظيف نص الـ JSON القادم من الذكاء الاصطناعي
let cleanText = String(rawText).replace(/```json/gi, '').replace(/```/g, '').trim();

let parsedData = [];
try {
    parsedData = JSON.parse(cleanText);
} catch (e) {
    const match = cleanText.match(/\[\s*\{[\s\S]*\}\s*\]/);
    if (match) {
        try { parsedData = JSON.parse(match[0]); } catch (err) {}
    }
}

if (!Array.isArray(parsedData)) parsedData = [];

// 3. جلب وتجميع كافة المنتجات من كل الصفحات (.all()) بشكل مرن
let rawProducts = [];
try {
    const allExtractItems = $("Extract Data of Page").all();
    allExtractItems.forEach(item => {
        const itemData = item.json;
        if (itemData) {
            // حالة 1: البيانات داخل مصفوفة raw_products
            if (Array.isArray(itemData.raw_products)) {
                rawProducts = rawProducts.concat(itemData.raw_products);
            } 
            // حالة 2: البيانات داخل عنصر raw_products مفرد
            else if (itemData.raw_products && typeof itemData.raw_products === 'object') {
                rawProducts.push(itemData.raw_products);
            }
            // حالة 3: العنصر نفسه يحتوي على بيانات المنتج مباشرة
            else if (itemData.title || itemData.price_EGP !== undefined) {
                rawProducts.push(itemData);
            }
        }
    });
} catch (err) {
    rawProducts = [];
}

// 4. الدمج واستخراج النتيجة النهائية
const finalRows = parsedData.map((aiSpecs, index) => {
    // جلب المنتج المقابل مع دعم الـ Index
    const rawItem = rawProducts[index] || {};
    const productData = rawItem.json ? rawItem.json : rawItem;

    // استخراج وتنظيف السعر (price_EGP) وإرجاعه كنص لتفادي مشاكل BigQuery
    let rawPrice = productData.price_EGP ?? productData.price ?? null;
    let priceStr = null;

    if (rawPrice !== null && rawPrice !== undefined) {
        if (typeof rawPrice === 'number') {
            priceStr = String(rawPrice);
        } else if (typeof rawPrice === 'string') {
            priceStr = rawPrice.replace(/[^0-9.]/g, '') || null;
        }
    }

    // استخراج التقييم (rating) وتحويله لنص
    let rating = productData.rating !== undefined && productData.rating !== null ? String(productData.rating) : null;

    // استخراج حالة التوفر (stock)
    let stock = productData.stock || productData.availability || null;

    return {
        json: {
            brand: aiSpecs.brand || null,

            // بيانات المعالج
            cpu: aiSpecs.cpu || null,
            cpu_brand: aiSpecs.cpu_brand || null,
            cpu_series: aiSpecs.cpu_series || null,

            ram: aiSpecs.ram || null,
            storage: aiSpecs.storage || null,

            // بيانات كارت الشاشة
            gpu: aiSpecs.gpu || null,
            gpu_brand: aiSpecs.gpu_brand || null,

            // المواصفات ونظام التشغيل
            screen_size: aiSpecs.screen_size || null,
            refresh_rate: aiSpecs.refresh_rate || null,
            operating_system: aiSpecs.operating_system || null,

            // بيانات متجر أمازون المباشرة
            price_EGP: priceStr,
            rating: rating,
            stock: stock ? String(stock) : null,
            url: productData.url || null,

            // التصنيفات الجديدة القادمة من نموذج الذكاء الاصطناعي
            performance_tier: aiSpecs.performance_tier || null,
            primary_use: aiSpecs.primary_use || null
        }
    };
});

return finalRows;
